ze_result_t zeInit(ze_init_flags_t flags) {
  _init_tracer();
  _init_tracer_dump();
  tracepoint(lttng_ust_ze, zeInit_entry, flags);
  ze_result_t _retval;
  _retval = ZE_INIT_PTR(flags);
  _in_loader_init = 0;
  tracepoint(lttng_ust_ze, zeInit_exit, flags, _retval);
  return _retval;
}

ze_result_t zeDriverGet(uint32_t *pCount, ze_driver_handle_t *phDrivers) {
  tracepoint(lttng_ust_ze, zeDriverGet_entry, pCount, phDrivers);
  ze_result_t _retval;
  _retval = ZE_DRIVER_GET_PTR(pCount, phDrivers);
  tracepoint(lttng_ust_ze, zeDriverGet_exit, pCount, phDrivers, _retval);
  return _retval;
}

ze_result_t zeInitDrivers(uint32_t *pCount, ze_driver_handle_t *phDrivers, ze_init_driver_type_desc_t *desc) {
  _init_tracer();
  tracepoint(lttng_ust_ze, zeInitDrivers_entry, pCount, phDrivers, desc);
  if (_do_chained_structs && desc)
    _print_lttng_ust_ze_structs(desc->pNext);
  ze_result_t _retval;
  _retval = ZE_INIT_DRIVERS_PTR(pCount, phDrivers, desc);
  tracepoint(lttng_ust_ze, zeInitDrivers_exit, pCount, phDrivers, desc, _retval);
  return _retval;
}

