ze_result_t zeModuleCreate(ze_context_handle_t hContext, ze_device_handle_t hDevice, const ze_module_desc_t *desc, ze_module_handle_t *phModule, ze_module_build_log_handle_t *phBuildLog) {
  tracepoint(lttng_ust_ze, zeModuleCreate_entry, hContext, hDevice, desc, phModule, phBuildLog);
  if (_do_chained_structs && desc)
    _print_lttng_ust_ze_structs(desc->pNext);
  int _build_log_release = 0;
  ze_module_build_log_handle_t _hBuildLog = NULL;
  if (tracepoint_enabled(lttng_ust_ze_build, log)) {
    if (phBuildLog == NULL) {
      phBuildLog = &_hBuildLog;
      _build_log_release = 1;
    }
  }
  ze_result_t _retval;
  _retval = ZE_MODULE_CREATE_PTR(hContext, hDevice, desc, phModule, phBuildLog);
  if (tracepoint_enabled(lttng_ust_ze_build, log) && (_retval == ZE_RESULT_SUCCESS || _retval == ZE_RESULT_ERROR_MODULE_BUILD_FAILURE) && *phBuildLog) {
    _dump_build_log(*phBuildLog);
    if (_build_log_release) {
      ZE_MODULE_BUILD_LOG_DESTROY_PTR(*phBuildLog);
      phBuildLog = NULL;
    }
  }
  tracepoint(lttng_ust_ze, zeModuleCreate_exit, hContext, hDevice, desc, phModule, phBuildLog, _retval);
  return _retval;
}

