ze_result_t zeCommandListAppendImageCopyToMemoryExt(ze_command_list_handle_t hCommandList, void *dstptr, ze_image_handle_t hSrcImage, const ze_image_region_t *pSrcRegion, uint32_t destRowPitch, uint32_t destSlicePitch, ze_event_handle_t hSignalEvent, uint32_t numWaitEvents, ze_event_handle_t *phWaitEvents) {
  tracepoint(lttng_ust_ze, zeCommandListAppendImageCopyToMemoryExt_entry, hCommandList, dstptr, hSrcImage, pSrcRegion, destRowPitch, destSlicePitch, hSignalEvent, numWaitEvents, phWaitEvents);
  if (_do_paranoid_memory_location &&
      (tracepoint_enabled(lttng_ust_ze_properties, memory_info_properties) || tracepoint_enabled(lttng_ust_ze_properties, memory_info_range))) {
    _dump_memory_info(hCommandList, dstptr);
  }
  ze_event_handle_t _user_signal = hSignalEvent;
  struct _ze_event_h * _einj = NULL;
  /* Resolved from the cl's stored context (no per-Append
   * zeCommandListGetContextHandle) and threaded to _record_append (epilogue). */
  ze_context_handle_t _ctx = NULL;
  if (_do_profile) {
    _einj = _get_event(hCommandList, &_ctx);
    if (_einj)
      hSignalEvent = _einj->event;
    /* If injection failed, fall through with the user's signal unchanged;
     * we won't be able to time this Append, but it still runs. */
  }
  if (_do_paranoid_drift &&
      ZE_DEVICE_GET_GLOBAL_TIMESTAMPS_PTR &&
      tracepoint_enabled(lttng_ust_ze_properties, device_timer))
    _dump_command_list_device_timer(hCommandList);
  ze_result_t _retval;
  _retval = ZE_COMMAND_LIST_APPEND_IMAGE_COPY_TO_MEMORY_EXT_PTR(hCommandList, dstptr, hSrcImage, pSrcRegion, destRowPitch, destSlicePitch, hSignalEvent, numWaitEvents, phWaitEvents);
  if (_do_profile && _einj) {
    if (_retval == ZE_RESULT_SUCCESS) {
      ze_event_handle_t _attr = _user_signal ? _user_signal : _einj->event;
      _record_append(hCommandList, _ctx, _einj, _user_signal,
                     phWaitEvents, numWaitEvents);
      tracepoint(lttng_ust_ze_profiling, event_profiling, _attr);
    } else {
      _put_event(_einj);
    }
  }
  tracepoint(lttng_ust_ze, zeCommandListAppendImageCopyToMemoryExt_exit, hCommandList, dstptr, hSrcImage, pSrcRegion, destRowPitch, destSlicePitch, hSignalEvent, numWaitEvents, phWaitEvents, _retval);
  return _retval;
}

