ze_result_t zesGetGlobalProcAddrTable(ze_api_version_t version, zes_global_dditable_t *pDdiTable) {
  tracepoint(lttng_ust_zes, zesGetGlobalProcAddrTable_entry, version, pDdiTable);
  ze_result_t _retval;
  if (!_do_ddi_table_forward && !_in_loader_init && pDdiTable && version <= ZE_API_VERSION_CURRENT) {
    if (version >= ZE_MAKE_VERSION(1,5)) {
      pDdiTable->pfnInit = zesInit_hid;
      _retval = ZE_RESULT_SUCCESS;
    } else
      goto ukn;
  } else {
ukn:
  _retval = ZES_GET_GLOBAL_PROC_ADDR_TABLE_PTR(version, pDdiTable);
  }
  tracepoint(lttng_ust_zes, zesGetGlobalProcAddrTable_exit, version, pDdiTable, _retval);
  return _retval;
}

